import type { ICtx } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { NavigationAgent3D } from "@threenative/physics/navigation";
import { attachToBone } from "@threenative/core";
import { Bone, type Group, Vector3 } from "three";
import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
import { directSpaceState } from "../physics.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const MOVE_SPEED = 2.8;
const DETECTION_RANGE = 12;
const STOP_DISTANCE = 1;
const PATROL_SPEED = 0.8;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  #patrol: NavigationAgent3D | undefined;
  #targetPosition: Vector3 | undefined;
  #chasing = false;
  #fireTimer = 0;
  #rifle: Group;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    patrolTargets: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    const rightHand = new Bone();
    rightHand.name = "RightHand";
    rightHand.position.set(0.3, 0.5, -0.5);
    this.mesh.add(rightHand);

    this.#rifle = createRifleVisual(materials);
    attachToBone(this.mesh, "RightHand", this.#rifle);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.35, 0.4),
      type: "dynamic",
    });

    this.#setupPatrol(patrolTargets);
  }

  #setupPatrol(patrolTargets: Vector3[]): void {
    if (patrolTargets.length === 0) return;
    let patrolIndex = 0;
    this.#targetPosition = patrolTargets[patrolIndex]?.clone();
  }

  #detectPlayer(ctx: GameCtx, playerPos: Vector3, playerBodyId: number): boolean {
    const distance = this.mesh.position.distanceTo(playerPos);
    if (distance > DETECTION_RANGE) {
      this.#chasing = false;
      return false;
    }

    const from = this.mesh.position.clone().add(new Vector3(0, 0.5, 0));
    const to = playerPos.clone().add(new Vector3(0, 0.5, 0));
    const hit = directSpaceState(ctx.physics).intersectRay({
      collisionMask: PLAYER_LAYER | WORLD_LAYER,
      from,
      to,
    });

    this.#chasing = hit?.body.id === playerBodyId;
    return this.#chasing;
  }

  update(
    ctx: GameCtx,
    dt: number,
    playerPos: Vector3,
    playerBodyId: number,
    patrolTargets: Vector3[],
  ): void {
    if (!this.alive) return;

    const canSeePlayer = this.#detectPlayer(ctx, playerPos, playerBodyId);

    if (canSeePlayer) {
      this.#targetPosition = playerPos.clone();
    } else if (patrolTargets.length > 0) {
      const distance = this.#targetPosition?.distanceTo(this.mesh.position) ?? Number.POSITIVE_INFINITY;
      if (distance < 1.5) {
        let nextIndex = patrolTargets.indexOf(this.#targetPosition as Vector3) + 1;
        if (nextIndex >= patrolTargets.length) nextIndex = 0;
        this.#targetPosition = patrolTargets[nextIndex]?.clone();
      }
    }

    if (this.#targetPosition) {
      const direction = this.#targetPosition
        .clone()
        .sub(this.mesh.position)
        .normalize();
      const distance = this.mesh.position.distanceTo(this.#targetPosition);
      const speed = this.#chasing ? MOVE_SPEED : PATROL_SPEED;

      if (distance > STOP_DISTANCE) {
        this.body.velocity.x = direction.x * speed;
        this.body.velocity.z = direction.z * speed;
      } else {
        this.body.velocity.x = 0;
        this.body.velocity.z = 0;
      }
    }

    this.body.moveAndSlide(dt);

    if (canSeePlayer && this.#chasing) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = 2;
        const origin = this.mesh.position.clone().add(new Vector3(0.3, 0.5, -0.5));
        this.#onFire(origin);
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.#chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

