    if (!this.alive) return;

    const canSeePlayer = this.#detectPlayer(ctx, playerPos, playerBodyId);

    if (canSeePlayer) {
      this.#targetPosition = playerPos.clone();
    } else if (patrolTargets.length > 0) {
      const distance = this.#targetPosition?.distanceTo(this.mesh.position) ?? Number.POSITIVE_INFINITY;
      if (distance < 1.5) {
        let nextIndex = patrolTargets.indexOf(this.#targetPosition as Vector3) + 1;
        if (nextIndex >= patrolTargets.length) nextIndex = 0;
        this.#targetPosition = patrolTargets[nextIndex]?.clone();
      }
    }

    if (this.#targetPosition) {
      const direction = this.#targetPosition
        .clone()
        .sub(this.mesh.position)
        .normalize();
      const distance = this.mesh.position.distanceTo(this.#targetPosition);
      const speed = this.#chasing ? MOVE_SPEED : PATROL_SPEED;

      if (distance > STOP_DISTANCE) {
        this.body.velocity.x = direction.x * speed;
        this.body.velocity.z = direction.z * speed;
      } else {
        this.body.velocity.x = 0;
        this.body.velocity.z = 0;
      }
    }

    this.body.moveAndSlide(dt);

    if (canSeePlayer && this.#chasing) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = 2;
        const origin = this.mesh.position.clone().add(new Vector3(0.3, 0.5, -0.5));
        this.#onFire(origin);
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.#chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

